export const runtime_settingsSchema = {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"AgentSettings":{"description":"Runtime-configurable local agent settings.","properties":{"completion":{"allOf":[{"$ref":"#/definitions/CompletionSettings"}],"default":{"max_tokens":null,"parallel_tool_calls":null,"prompt_cache":null,"reasoning_effort":null,"seed":null,"stop":[],"temperature":null,"tool_choice":{"mode":"auto"},"top_p":null},"description":"Sampling / generation parameters."},"hooks":{"allOf":[{"$ref":"#/definitions/HookSettings"}],"default":{"enabled":true,"log":""},"description":"Observable lifecycle hooks."},"max_steps":{"default":50,"description":"Maximum model/tool steps per turn (`1..=200`; default 50).","format":"uint","minimum":0.0,"type":"integer"},"memory":{"allOf":[{"$ref":"#/definitions/MemorySettings"}],"default":{"dir":"","enabled":true},"description":"Multi-turn conversation memory."},"schedule":{"allOf":[{"$ref":"#/definitions/ScheduleSettings"}],"default":{"enabled":false,"scan_seconds":10},"description":"Workspace schedule auto-run (disabled by default)."}},"type":"object"},"ApprovalPolicy":{"description":"Closed local approval policy for tool calls (config spec C-1).\n\nThe policy only decides whether the agent asks the user before running a tool. It can never auto-approve a tool whose `ToolSpec.requires_approval` is true (weak invariant T1); the only exception is the per-conversation always-allow set owned by the approval spec (S4), which is an explicit earlier user authorization, not a policy decision.","oneOf":[{"description":"Ask exactly for tools that declare `requires_approval` (default).","enum":["ask"],"type":"string"},{"description":"Read-only tools run without asking; every mutating tool asks.","enum":["auto_read_only"],"type":"string"},{"description":"Ask for every tool call, including read-only ones (strictest).","enum":["strict"],"type":"string"}]},"CompletionSettings":{"description":"Sampling / generation parameters for the local agent.","properties":{"max_tokens":{"default":null,"description":"Output-token cap; omitted keeps the provider default.","format":"uint64","minimum":0.0,"type":["integer","null"]},"parallel_tool_calls":{"default":null,"description":"Whether the provider may run tool calls in parallel.","type":["boolean","null"]},"prompt_cache":{"default":null,"description":"Prompt-cache retention: `short|long`.","type":["string","null"]},"reasoning_effort":{"default":null,"description":"Portable reasoning effort: `minimal|low|medium|high|xhigh|max`.","type":["string","null"]},"seed":{"default":null,"description":"Sampling seed for reproducible runs.","format":"uint64","minimum":0.0,"type":["integer","null"]},"stop":{"default":[],"description":"Stop sequences.","items":{"type":"string"},"type":"array"},"temperature":{"default":null,"description":"Sampling temperature (`0.0..=2.0`); omitted keeps the provider default.","format":"double","type":["number","null"]},"tool_choice":{"allOf":[{"$ref":"#/definitions/ToolChoiceSetting"}],"default":{"mode":"auto"},"description":"Tool-selection policy."},"top_p":{"default":null,"description":"Nucleus sampling (`0.0..=1.0`); omitted keeps the provider default.","format":"double","type":["number","null"]}},"type":"object"},"HookSettings":{"description":"Observable agent lifecycle hooks configuration.","properties":{"enabled":{"default":true,"description":"Whether lifecycle hook events are emitted.","type":"boolean"},"log":{"default":"","description":"Optional JSONL file that receives the hook events (append-only).","type":"string"}},"type":"object"},"MemorySettings":{"description":"Multi-turn conversation memory for the local agent.","properties":{"dir":{"default":"","description":"Memory directory; empty means `$ZEOKEEL_HOME/agent-memory`.","type":"string"},"enabled":{"default":true,"description":"Whether conversation memory is enabled.","type":"boolean"}},"type":"object"},"ScheduleSettings":{"description":"Workspace schedule auto-run settings (`docs/19`/`docs/38`).\n\nAuto-run starts scheduled prompts with no human in the loop, so it is **disabled by default**; the desktop executor always starts but idles while disabled. `scan_seconds` is the poll period for due schedules.","properties":{"enabled":{"default":false,"description":"Whether the desktop executes due `.zeokeel/schedules.json` entries.","type":"boolean"},"scan_seconds":{"default":10,"description":"Schedule scan period in seconds (`5..=3600`; default 10).","format":"uint64","maximum":3600.0,"minimum":5.0,"type":"integer"}},"type":"object"},"ToolChoiceSetting":{"description":"How the model may choose tools for a turn.","oneOf":[{"description":"The model decides (default).","properties":{"mode":{"enum":["auto"],"type":"string"}},"required":["mode"],"type":"object"},{"description":"No tool may be called.","properties":{"mode":{"enum":["none"],"type":"string"}},"required":["mode"],"type":"object"},{"description":"At least one tool must be called.","properties":{"mode":{"enum":["required"],"type":"string"}},"required":["mode"],"type":"object"},{"description":"Only the listed tools may be called.","properties":{"mode":{"enum":["specific"],"type":"string"},"tools":{"items":{"type":"string"},"type":"array"}},"required":["mode","tools"],"type":"object"}]},"ToolSettings":{"description":"Tool execution and approval-wait timeouts for the local agent.","properties":{"approval_policy":{"anyOf":[{"$ref":"#/definitions/ApprovalPolicy"},{"type":"null"}],"default":null,"description":"Explicit local approval policy (`None` = default `ask`, not published)."},"approval_timeout_ms":{"default":300000,"description":"Approval wait timeout in milliseconds (1000..=1800000).","format":"uint64","minimum":0.0,"type":"integer"},"tool_timeout_ms":{"default":120000,"description":"Per-tool-call timeout in milliseconds (1000..=600000).","format":"uint64","minimum":0.0,"type":"integer"}},"type":"object"},"WebSearchSettings":{"description":"Web-search tool endpoint settings (`tool.web_search`).\n\nThe search tool calls a keyless DuckDuckGo-compatible instant-answer endpoint, so this section carries **no credential**. It is a tool egress endpoint (not an AI provider), therefore C7 does not apply: both editions may point the tool at their own endpoint (C6 weak control). The runtime resolves **explicit settings > `ZEOKEEL_SEARCH_URL` > built-in default** and requires https. `schemars` bounds the timeout so the generated Ajv schema rejects out-of-range values before Rust validation runs (C10).","properties":{"base_url":{"default":"","description":"Endpoint base URL (https only); empty = fall back to the env/default.","type":"string"},"timeout_ms":{"default":15000,"description":"Request timeout in milliseconds (`1000..=120000`; default 15000).","format":"uint64","maximum":120000.0,"minimum":1000.0,"type":"integer"}},"type":"object"}},"description":"Non-secret settings snapshot published to the local agent runtime.\n\nDeliberately contains no `ProviderConfig`: provider credentials/base URLs are host/secret-store concerns and must never be readable by every package linked against the config contract (review round-3 P2). Only the sections the runtime needs on each turn are published.","properties":{"agent":{"anyOf":[{"$ref":"#/definitions/AgentSettings"},{"type":"null"}],"description":"Runtime agent settings, when explicitly saved (non-default).\n\n`None` means \"not published\": the runtime keeps the env/default fallback for the agent section instead of overriding it."},"tools":{"anyOf":[{"$ref":"#/definitions/ToolSettings"},{"type":"null"}],"description":"Tool execution / approval-wait timeouts, when explicitly saved.\n\n`None` means \"not published\": the runtime keeps the env/default fallback for the tools section."},"web_search":{"anyOf":[{"$ref":"#/definitions/WebSearchSettings"},{"type":"null"}],"description":"Web-search tool endpoint, when explicitly saved.\n\n`None` means \"not published\": `tool-web-search` keeps its `ZEOKEEL_SEARCH_URL` env fallback and the built-in DuckDuckGo default."}},"title":"RuntimeSettings","type":"object"} as const;

