export const web_search_settingsSchema = {"$schema":"http://json-schema.org/draft-07/schema#","description":"Web-search tool endpoint settings (`tool.web_search`).\n\nThe search tool calls a keyless DuckDuckGo-compatible instant-answer endpoint, so this section carries **no credential**. It is a tool egress endpoint (not an AI provider), therefore C7 does not apply: both editions may point the tool at their own endpoint (C6 weak control). The runtime resolves **explicit settings > `ZEOKEEL_SEARCH_URL` > built-in default** and requires https. `schemars` bounds the timeout so the generated Ajv schema rejects out-of-range values before Rust validation runs (C10).","properties":{"base_url":{"default":"","description":"Endpoint base URL (https only); empty = fall back to the env/default.","type":"string"},"timeout_ms":{"default":15000,"description":"Request timeout in milliseconds (`1000..=120000`; default 15000).","format":"uint64","maximum":120000.0,"minimum":1000.0,"type":"integer"}},"title":"WebSearchSettings","type":"object"} as const;

export const workspace_changeSchema = {"$schema":"http://json-schema.org/draft-07/schema#","description":"One changed path from `workspace.changes`.","properties":{"add":{"description":"Coarse added/untracked/modified marker (`1` when this path is not a deletion).","format":"uint32","minimum":0.0,"type":"integer"},"del":{"description":"Coarse deleted marker (`1` when git reports a deletion).","format":"uint32","minimum":0.0,"type":"integer"},"path":{"description":"Path relative to the workspace root (forward slashes when git reports them).","type":"string"}},"required":["add","del","path"],"title":"WorkspaceChange","type":"object"} as const;

export const workspace_changes_resultSchema = {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"WorkspaceChange":{"description":"One changed path from `workspace.changes`.","properties":{"add":{"description":"Coarse added/untracked/modified marker (`1` when this path is not a deletion).","format":"uint32","minimum":0.0,"type":"integer"},"del":{"description":"Coarse deleted marker (`1` when git reports a deletion).","format":"uint32","minimum":0.0,"type":"integer"},"path":{"description":"Path relative to the workspace root (forward slashes when git reports them).","type":"string"}},"required":["add","del","path"],"type":"object"}},"description":"`workspace.changes` result: bounded, read-only git working-tree summary.\n\n`warning` is present when git is unavailable / the workspace is not a repository / the output was truncated; `items` is empty in those cases where no reliable listing is available.","properties":{"items":{"description":"Changed paths, sorted by path (bounded by the host).","items":{"$ref":"#/definitions/WorkspaceChange"},"type":"array"},"warning":{"description":"Human-readable non-fatal warning (omitted when the scan was clean).","type":["string","null"]}},"required":["items"],"title":"WorkspaceChangesResult","type":"object"} as const;

export const workspace_file_read_resultSchema = {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"FileReadKind":{"description":"Kind of a `workspace.file_read` result.","oneOf":[{"description":"UTF-8 text content (`encoding = utf8`).","enum":["text"],"type":"string"},{"description":"Raster image content (`encoding = base64`).","enum":["image"],"type":"string"},{"description":"Honest degradation: PDF/Office/HTML/binary/too large/symlink escape.","enum":["unsupported"],"type":"string"}]}},"description":"One `workspace.file_read` result (read-only, workspace relative).","properties":{"content":{"description":"Content (empty when unsupported).","type":"string"},"encoding":{"description":"`utf8` | `base64` | empty (unsupported).","type":"string"},"kind":{"allOf":[{"$ref":"#/definitions/FileReadKind"}],"description":"Content kind."},"mime":{"description":"Detected MIME (`text/*`/`image/*`; may be `application/octet-stream`).","type":"string"},"path":{"description":"Workspace-relative path (forward slashes).","type":"string"},"reason":{"default":"","description":"User-readable degradation reason (empty when supported).","type":"string"},"size":{"description":"Full file size in bytes.","format":"uint64","minimum":0.0,"type":"integer"},"truncated":{"description":"Content was truncated to the host limit (text only).","type":"boolean"}},"required":["content","encoding","kind","mime","path","size","truncated"],"title":"WorkspaceFileReadResult","type":"object"} as const;

export const workspace_files_resultSchema = {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"FileEntry":{"description":"One bounded entry of a read-only workspace file listing (`workspace.files`).\n\nMirrors the host emission `{ \"path\", \"depth\", \"kind\" }` in `apps/desktop/src/ipc.rs::list_workspace_files`; `badge` is optional UI metadata for inspectors (absent on the current wire).","properties":{"badge":{"default":"","description":"Optional inspector badge (empty/absent when the entry has none).","type":"string"},"depth":{"description":"Depth relative to the workspace root (`0` = direct child).","format":"uint32","minimum":0.0,"type":"integer"},"kind":{"allOf":[{"$ref":"#/definitions/FileKind"}],"description":"Entry kind."},"path":{"description":"Path relative to the workspace root (forward slashes; depth-bounded).","type":"string"}},"required":["depth","kind","path"],"type":"object"},"FileKind":{"description":"Kind of one workspace file-listing entry (`workspace.files`).","oneOf":[{"description":"Directory (may be expanded).","enum":["dir"],"type":"string"},{"description":"Regular file.","enum":["file"],"type":"string"}]}},"description":"`workspace.files` result: bounded read-only entries under one workspace root.\n\nThe host emits `{ \"items\": [...] }` (`list_workspace_files`); the field is named `items` to stay wire-compatible with the current desktop/web parsers.","properties":{"items":{"description":"Entries sorted by path (bounded by the host).","items":{"$ref":"#/definitions/FileEntry"},"type":"array"}},"required":["items"],"title":"WorkspaceFilesResult","type":"object"} as const;

